
-- =============================================
-- Create date: <Create Date,29-01-2024>
-- Description:	<Description,Stored procedure que lista la información de la ficha distrital 903>
-- =============================================

CREATE PROCEDURE [dbo].[SP_HC_ListarFichaDistrital903]
(
  @IdFicha as Int,
  @NumFicha as varchar(10)
)

AS
BEGIN
  SET NOCOUNT ON;
		
		Select
				OtherNeighborhood as 'OtroBarrio', CASE EducationLevel WHEN 1 THEN 1 ELSE 0 END AS 'No escuela', CASE EducationLevel WHEN 2 THEN 1 ELSE 0 END AS 'Preescolar',
				CASE EducationLevel WHEN 3 THEN 1 ELSE 0 END AS 'Primaria incompleta',CASE EducationLevel WHEN 4 THEN 1 ELSE 0 END AS 'Primaria completa', CASE EducationLevel WHEN 5 THEN 1 ELSE 0 END AS 'Secundaria incompleta', CASE EducationLevel WHEN 6 THEN 1 ELSE 0 END AS 'Secundaria completa',
				CASE EducationLevel WHEN 7 THEN 1 ELSE 0 END AS 'Tecnico incompleta', CASE EducationLevel WHEN 8 THEN 1 ELSE 0 END AS 'Tecnico completa', CASE EducationLevel WHEN 9 THEN 1 ELSE 0 END AS 'Universidad incompleta', CASE EducationLevel WHEN 10 THEN 1 ELSE 0 END AS 'Universidad completa',
				CASE EducationLevel WHEN 11 THEN 1 ELSE 0 END AS 'Postgrado incompleta', CASE EducationLevel WHEN 12 THEN 1 ELSE 0 END AS 'Postgrado completa', CASE EducationLevel WHEN 13 THEN 1 ELSE 0 END AS 'Sin dato educacion', CASE CivilStatus WHEN 1 THEN 1 ELSE 0 END AS 'Soltero', 
				CASE CivilStatus WHEN 2 THEN 1 ELSE 0 END AS 'Casado', CASE CivilStatus WHEN 3 THEN 1 ELSE 0 END AS 'Divorciado', CASE CivilStatus WHEN 4 THEN 1 ELSE 0 END AS 'Separado', CASE CivilStatus WHEN 5 THEN 1 ELSE 0 END AS 'Viudo',CASE CivilStatus WHEN 6 THEN 1 ELSE 0 END AS 'Unión libre',
				CASE CivilStatus WHEN 7 THEN 1 ELSE 0 END AS 'Sin dato civil', CountryOfOrigin as 'PaísNacimiento', MunicipalityOfOrigin as 'MunicipioProcedencia', DepartmentOfOrigin as 'DepartamentoProcedencia', format(IncidenceDate, 'dd/MM/yyyy') as 'FechaOcurrencia', format(IncidenceDate, 'HH:mm') as 'HoraOcurrencia',
				LocalityOccurrence as 'LocalidadOcurrencia', NeighborhoodOfOccurrence as 'BarrioOcurrencia', UPZ as 'UPZ', CASE AreaOfOccurrence WHEN 1 THEN 'Urbana' WHEN 2 THEN 'Rural' END AS 'AreaOcurrencia', TRY_CAST( JSON_VALUE(InjuryOf,'$.TRANSITO') AS BIT) AS 'TRANSITOLesion',
				TRY_CAST( JSON_VALUE(InjuryOf,'$.CONSUMO') AS BIT) AS 'CONSUMOLesion', TRY_CAST( JSON_VALUE(InjuryOf,'$.PROCEDIMIENTOSESTETICOS') AS BIT) AS 'PROCEDIMIENTOSESTETICOSLesion', TRY_CAST( JSON_VALUE(InjuryOf,'$.OTROTIPO') AS BIT) AS 'OTROTIPOLesion', 
				TRY_CAST( JSON_VALUE(InjuryOf,'$.AUTOINFLINGIDAS') AS BIT) AS 'AUTOINFLINGIDASLesion', TRY_CAST( JSON_VALUE(InjuryOf,'$.PORTERCEROS') AS BIT) AS 'PORTERCEROSLesion', CASE TypoeOfService WHEN 1 THEN 1 ELSE 0 END AS 'TipoServicioPublico', CASE TypoeOfService WHEN 2 THEN 1 ELSE 0 END AS 'TipoServicioPrivado',
				CASE TransportMode WHEN 1 THEN 1 ELSE 0 END AS 'ModalidadTransporteIndividual', CASE TransportMode WHEN 2 THEN 1 ELSE 0 END AS 'ModalidadTransporteColectivo', CASE TransportMode WHEN 3 THEN 1 ELSE 0 END AS 'ModalidadTransporteMasivo', CASE TransportMode WHEN 4 THEN 1 ELSE 0 END AS 'ModalidadTransporteCarga',
				CASE VehicleType WHEN 1 THEN 1 ELSE 0 END AS 'TipoVehiculoAutomovil', CASE VehicleType WHEN 2 THEN 1 ELSE 0 END AS 'TipoVehiculoMoto', CASE VehicleType WHEN 3 THEN 1 ELSE 0 END AS 'TipoVehiculoBicicleta', CASE VehicleType WHEN 4 THEN 1 ELSE 0 END AS 'TipoVehiculoTaxi',
				CASE VehicleType WHEN 5 THEN 1 ELSE 0 END AS 'TipoVehiculoAmbulancia', CASE VehicleType WHEN 6 THEN 1 ELSE 0 END AS 'TipoVehiculoBicitaxi', CASE VehicleType WHEN 7 THEN 1 ELSE 0 END AS 'TipoVehiculoMototaxi', CASE VehicleType WHEN 8 THEN 1 ELSE 0 END AS 'TipoVehiculoCamioneta',
				CASE VehicleType WHEN 9 THEN 1 ELSE 0 END AS 'TipoVehiculoBus', CASE VehicleType WHEN 10 THEN 1 ELSE 0 END AS 'TipoVehiculoTransmilenio', CASE VehicleType WHEN 11 THEN 1 ELSE 0 END AS 'TipoVehiculoSITP', CASE VehicleType WHEN 12 THEN 1 ELSE 0 END AS 'TipoVehiculoVCarga', CASE ConditionOfTheInjured WHEN 1 THEN 1 ELSE 0 END AS 'CondicionLesionadoPeaton',
				CASE ConditionOfTheInjured WHEN 2 THEN 1 ELSE 0 END AS 'CondicionLesionadoPasajero',CASE ConditionOfTheInjured WHEN 3 THEN 1 ELSE 0 END AS 'CondicionLesionadoConductor', CASE ConditionOfTheInjured WHEN 4 THEN 1 ELSE 0 END AS 'CondicionLesionadoCopiloto', CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.ESTRANGULAMIENTO') AS BIT) WHEN 1 THEN 'X' END AS 'ESTRANGULAMIENTOTipoConsumo',
				CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.HERIDA') AS BIT) WHEN 1 THEN 'X' END AS 'HERIDATipoConsumo', CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.INFECCION') AS BIT) WHEN 1 THEN 'X' END AS 'INFECCIONTipoConsumo', CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.INTOXICACION') AS BIT) WHEN 1 THEN 'X' END AS 'INTOXICACIONTipoConsumo',
				CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.SEPSIS') AS BIT) WHEN 1 THEN 'X' END AS 'SEPSISTipoConsumo', CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.PERFORACION') AS BIT) WHEN 1 THEN 'X' END AS 'PERFORACIONTipoConsumo', CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.HEMORRAGIA') AS BIT) WHEN 1 THEN 'X' END AS 'HEMORRAGIATipoConsumo',
				CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.NECROSIS') AS BIT) WHEN 1 THEN 'X' END AS 'NECROSISTipoConsumo', CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.EMBOLIA') AS BIT) WHEN 1 THEN 'X' END AS 'EMBOLIATipoConsumo',CASE TRY_CAST( JSON_VALUE(ConsumptionInjuryType,'$.DEPRESION') AS BIT) WHEN 1 THEN 'X' END AS 'DEPRESIONTipoConsumo',
				CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.INFECCION') AS BIT) WHEN 1 THEN 'X' END AS 'INFECCIONTipoLesionEstetica', CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.SEPSIS') AS BIT) WHEN 1 THEN 'X' END AS 'SEPSISTipoLesionEstetica', CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.PERFORACION') AS BIT) WHEN 1 THEN 'X' END AS 'PERFORACIONTipoLesionEstetica',
				CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.HEMORRAGIA') AS BIT) WHEN 1 THEN 'X' END AS 'HEMORRAGIATipoLesionEstetica', CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.NECROSIS') AS BIT) WHEN 1 THEN 'X' END AS 'NECROSISTipoLesionEstetica', CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.EMBOLIA') AS BIT) WHEN 1 THEN 'X' END AS 'EMBOLIATipoLesionEstetica',
				CASE TRY_CAST( JSON_VALUE(TypeOfAestheticInjury,'$.DEPRESION') AS BIT) WHEN 1 THEN 'X' END AS 'DEPRESIONTipoLesionEstetica', CASE NoOfSurgicalProcedure WHEN 1 THEN 1 ELSE 0 END AS 'NoProcedimientos1', CASE NoOfSurgicalProcedure WHEN 2 THEN 1 ELSE 0 END AS 'NoProcedimientos2', CASE NoOfSurgicalProcedure WHEN 3 THEN 1 ELSE 0 END AS 'NoProcedimientos3',
				CASE NoOfSurgicalProcedure WHEN 4 THEN 1 ELSE 0 END AS 'NoProcedimientosMas', CASE TypeOfAestheticProfessional WHEN 1 THEN 1 ELSE 0 END AS 'TipoProfesionalSalud', CASE TypeOfAestheticProfessional WHEN 2 THEN 1 ELSE 0 END AS 'TipoProfesionalCirujano', CASE TypeOfAestheticProfessional WHEN 3 THEN 1 ELSE 0 END AS 'TipoProfesionalMedicoEsteticista',
				CASE TypeOfAestheticProfessional WHEN 4 THEN 1 ELSE 0 END AS 'TipoProfesionalEspecialista', CASE TypeOfAestheticProfessional WHEN 5 THEN 1 ELSE 0 END AS 'TipoProfesionalEsteticista', CASE TypeOfAestheticProfessional WHEN 6 THEN 1 ELSE 0 END AS 'TipoProfesionalCosmetologo', WhichInjuryOf as 'CualTipoLesion',
				CASE TypeOfAbuse WHEN 1 THEN 1 ELSE 0 END AS 'TipoMaltratoViolenciaComun', CASE TypeOfAbuse WHEN 2 THEN 1 ELSE 0 END AS 'TipoMaltratoDelitoSexual', CASE TypeOfAbuse WHEN 3 THEN 1 ELSE 0 END AS 'TipoMaltratoViolenciaConyugal', CASE TypeOfAbuse WHEN 4 THEN 1 ELSE 0 END AS 'TipoMaltratoMaltratoMenor',
				CASE TypeOfAbuse WHEN 5 THEN 1 ELSE 0 END AS 'TipoMaltratoViolenciaIntrafamiliar',CASE TypeOfAbuse WHEN 6 THEN 1 ELSE 0 END AS 'TipoMaltratoViolenciaInstitucional', CASE AllegedAggressor WHEN 1 THEN 1 ELSE 0 END AS 'PresuntoAgresorFamiliar', CASE AllegedAggressor WHEN 2 THEN 1 ELSE 0 END AS 'PresuntoAgresorConocido',
				CASE AllegedAggressor WHEN 3 THEN 1 ELSE 0 END AS 'PresuntoAgresorDesconocido', CASE SexOfAggressor WHEN 1 THEN 1 ELSE 0 END AS 'SexoAgresorHombre', CASE SexOfAggressor WHEN 2 THEN 1 ELSE 0 END AS 'SexoAgresorMujer', CASE SexOfAggressor WHEN 3 THEN 1 ELSE 0 END AS 'SexoAgresorDesconocido',
				CASE WasReported WHEN 1 THEN 1 ELSE 0 END AS 'FueDenunciadoSi', CASE WasReported WHEN 0 THEN 1 ELSE 0 END AS 'FueDenunciadoNo', CASE SPAVictim WHEN 1 THEN 1 ELSE 0 END AS 'SPAVictimaSi', CASE SPAVictim WHEN 0 THEN 1 ELSE 0 END AS 'SPAVictimaNo', CASE AlcoholVictim WHEN 1 THEN 1 ELSE 0 END AS 'AlcoholVictimaSi',
				CASE AlcoholVictim WHEN 0 THEN 1 ELSE 0 END AS 'AlcoholVictimaNo', CASE OthersVictim WHEN 1 THEN 1 ELSE 0 END AS 'OtrosVictimaSi', CASE OthersVictim WHEN 0 THEN 1 ELSE 0 END AS 'OtrosVictimaNo', CASE SPAAggressor WHEN 1 THEN 1 ELSE 0 END AS 'SPAAgresorSi', CASE SPAAggressor WHEN 0 THEN 1 ELSE 0 END AS 'SPAAgresorNo',
				CASE AlcoholAggressor WHEN 1 THEN 1 ELSE 0 END AS 'AlcoholAgresorSi', CASE AlcoholAggressor WHEN 0 THEN 1 ELSE 0 END AS 'AlcoholAgresorNo',  CASE OthersAggressor WHEN 1 THEN 1 ELSE 0 END AS 'OtrosAgresorSi', CASE OthersAggressor WHEN 0 THEN 1 ELSE 0 END AS 'OtrosAgresorNo',
				CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.ARMAFUEGO') AS BIT) WHEN 1 THEN 'X' END AS 'ARMAFUEGOMecanismoElemento', CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.ARMACORTOPUNZANTE') AS BIT) WHEN 1 THEN 'X' END AS 'ARMACORTOPUNZANTEMecanismoElemento', 
				CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.ARMACONTUNDENTE') AS BIT) WHEN 1 THEN 'X' END AS 'ARMACONTUNDENTEMecanismoElemento', CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.CAIDAPROPIA') AS BIT) WHEN 1 THEN 'X' END AS 'CAIDAPROPIAMecanismoElemento', 
				CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.CAIDAELEVADO') AS BIT) WHEN 1 THEN 'X' END AS 'CAIDAELEVADOMecanismoElemento', CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.AHOGAMIENTO') AS BIT) WHEN 1 THEN 'X' END AS 'AHOGAMIENTOMecanismoElemento', 
				CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.OTROMECANISMO') AS BIT) WHEN 1 THEN 'X' END AS 'OTROMECANISMOMecanismoElemento', CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.ARTICULOCONSUMO') AS BIT) WHEN 1 THEN 'X' END AS 'ARTICULOCONSUMOMecanismoElemento',
				CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.ARTICULOBELLEZA') AS BIT) WHEN 1 THEN 'X' END AS 'ARTICULOBELLEZAMecanismoElemento',CASE TRY_CAST( JSON_VALUE(MechanismOrElement,'$.QUEMADURA') AS BIT) WHEN 1 THEN 'X' END AS 'QUEMADURAMecanismoElemento', CASE TypeOfDrowning WHEN 1 THEN 1 ELSE 0 END AS 'TipoAhogamientoAsfixia',
				CASE TypeOfDrowning WHEN 2 THEN 1 ELSE 0 END AS 'TipoAhogamientoInmersion', WhichMechanism as 'CualMecanismo', WhichConsumerItem as 'CualArticuloConsumo', WhichBeautyItem as 'CualArticuloBelleza', CASE TRY_CAST( JSON_VALUE(BurnType,'$.LIQUIDO') AS BIT) WHEN 1 THEN 'X' END AS 'LIQUIDOTipoQuemadura',
				CASE TRY_CAST( JSON_VALUE(BurnType,'$.LLAMA') AS BIT) WHEN 1 THEN 'X' END AS 'LLAMATipoQuemadura', CASE TRY_CAST( JSON_VALUE(BurnType,'$.ELECTRICIDAD') AS BIT) WHEN 1 THEN 'X' END AS 'ELECTRICIDADTipoQuemadura', CASE TRY_CAST( JSON_VALUE(BurnType,'$.SOLIDO') AS BIT) WHEN 1 THEN 'X' END AS 'SOLIDOTipoQuemadura',
				CASE TRY_CAST( JSON_VALUE(BurnType,'$.VAPOR') AS BIT) WHEN 1 THEN 'X' END AS 'VAPORTipoQuemadura', CASE TRY_CAST( JSON_VALUE(BurnType,'$.SOLAR') AS BIT) WHEN 1 THEN 'X' END AS 'SOLARTipoQuemadura', CASE TRY_CAST( JSON_VALUE(BurnType,'$.RAYO') AS BIT) WHEN 1 THEN 'X' END AS 'RAYOTipoQuemadura',
				CASE TRY_CAST( JSON_VALUE(BurnType,'$.QUIMICO') AS BIT) WHEN 1 THEN 'X' END AS 'QUIMICOTipoQuemadura', CASE TRY_CAST( JSON_VALUE(BurnType,'$.POLVORA') AS BIT) WHEN 1 THEN 'X' END AS 'POLVORATipoQuemadura', CASE CauseOfChemicalInjury WHEN 1 THEN 1 ELSE 0 END AS 'LesionQuimicoAccidente',
				CASE CauseOfChemicalInjury WHEN 2 THEN 1 ELSE 0 END AS 'LesionQuimicoAgresion', CASE GunpowderType WHEN 1 THEN 1 ELSE 0 END AS 'TipoPolvoraPirotecnia', CASE GunpowderType WHEN 2 THEN 1 ELSE 0 END AS 'TipoPolvoraNegra', CASE GunpowderType WHEN 3 THEN 1 ELSE 0 END AS 'TipoPolvoraExplosiva',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.CRANEO') AS BIT) WHEN 1 THEN 'X' END AS 'CRANEOSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.MANO') AS BIT) WHEN 1 THEN 'X' END AS 'MANOSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.MUSLO') AS BIT) WHEN 1 THEN 'X' END AS 'MUSLOSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.CARA') AS BIT) WHEN 1 THEN 'X' END AS 'CARASitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.DEDOSMANO') AS BIT) WHEN 1 THEN 'X' END AS 'DEDOSMANOSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.PIERNAS') AS BIT) WHEN 1 THEN 'X' END AS 'PIERNASSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.OJOS') AS BIT) WHEN 1 THEN 'X' END AS 'OJOSSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.TORAXANTERIOR') AS BIT) WHEN 1 THEN 'X' END AS 'TORAXANTERIORSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.PIES') AS BIT) WHEN 1 THEN 'X' END AS 'PIESSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.NARIZ') AS BIT) WHEN 1 THEN 'X' END AS 'NARIZSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.TORAXPOSTERIOR') AS BIT) WHEN 1 THEN 'X' END AS 'TORAXPOSTERIORSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.DEDOSPIES') AS BIT) WHEN 1 THEN 'X' END AS 'DEDOSPIESSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.OREJAS') AS BIT) WHEN 1 THEN 'X' END AS 'OREJASSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.MAMAS') AS BIT) WHEN 1 THEN 'X' END AS 'MAMASSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.ORGANOSINTERNOS') AS BIT) WHEN 1 THEN 'X' END AS 'ORGANOSINTERNOSSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.BOCADIENTES') AS BIT) WHEN 1 THEN 'X' END AS 'BOCADIENTESSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.ABDOMEN') AS BIT) WHEN 1 THEN 'X' END AS 'ABDOMENSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.PIEL') AS BIT) WHEN 1 THEN 'X' END AS 'PIELSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.CUELLO') AS BIT) WHEN 1 THEN 'X' END AS 'CUELLOSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.PELVISPERINEO') AS BIT) WHEN 1 THEN 'X' END AS 'PELVISPERINEOSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.BRAZO') AS BIT) WHEN 1 THEN 'X' END AS 'BRAZOSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.GENITALES') AS BIT) WHEN 1 THEN 'X' END AS 'GENITALESSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.ANTEBRAZO') AS BIT) WHEN 1 THEN 'X' END AS 'ANTEBRAZOSitioAnatomico', CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.GLUTEOS') AS BIT) WHEN 1 THEN 'X' END AS 'GLUTEOSSitioAnatomico',
				CASE TRY_CAST( JSON_VALUE(AnatomicalSite,'$.VIAAEREA') AS BIT) WHEN 1 THEN 'X' END AS 'VIAAEREASitioAnatomico', CASE LocationOfTheEvent WHEN 1 THEN 1 ELSE 0 END AS 'LugarHechoCerrado', CASE LocationOfTheEvent WHEN 2 THEN 1 ELSE 0 END AS 'LugarHechoAbierto', CASE Grade WHEN 1 THEN 1 ELSE 0 END AS 'PrimerGrado',
				CASE Grade WHEN 2 THEN 1 ELSE 0 END AS 'SegundoGrado', CASE Grade WHEN 3 THEN 1 ELSE 0 END AS 'TercerGrado', CASE Extension WHEN 1 THEN 1 ELSE 0 END AS 'ExtensionMenor', CASE Extension WHEN 2 THEN 1 ELSE 0 END AS 'ExtensionDel', CASE Extension WHEN 3 THEN 1 ELSE 0 END AS 'ExtensionMayor',
				CASE TRY_CAST( JSON_VALUE(Scenery,'$.VIVIENDA') AS BIT) WHEN 1 THEN 'X' END AS 'VIVIENDAEscenario',CASE TRY_CAST( JSON_VALUE(Scenery,'$.TRABAJO') AS BIT) WHEN 1 THEN 'X' END AS 'TRABAJOEscenario', CASE TRY_CAST( JSON_VALUE(Scenery,'$.ESTUDIO') AS BIT) WHEN 1 THEN 'X' END AS 'ESTUDIOEscenario',
				CASE TRY_CAST( JSON_VALUE(Scenery,'$.BARES') AS BIT) WHEN 1 THEN 'X' END AS 'BARESEscenario', CASE TRY_CAST( JSON_VALUE(Scenery,'$.OTROSESTABLECIMIENTOS') AS BIT) WHEN 1 THEN 'X' END AS 'OTROSESTABLECIMIENTOSEscenario', CASE TRY_CAST( JSON_VALUE(Scenery,'$.VIAS') AS BIT) WHEN 1 THEN 'X' END AS 'VIASEscenario',
				CASE TRY_CAST( JSON_VALUE(Scenery,'$.TRANSPORTE') AS BIT) WHEN 1 THEN 'X' END AS 'TRANSPORTEEscenario', CASE TRY_CAST( JSON_VALUE(Scenery,'$.INSTITUCIONES') AS BIT) WHEN 1 THEN 'X' END AS 'INSTITUCIONESEscenario', CASE TRY_CAST( JSON_VALUE(Scenery,'$.OTRO') AS BIT) WHEN 1 THEN 'X' END AS 'OTROEscenario',
				CASE TypeOfJob WHEN 1 THEN 1 ELSE 0 END AS 'TipoTrabajoFormal', CASE TypeOfJob WHEN 2 THEN 1 ELSE 0 END AS 'TipoTrabajoInformal', CASE WorkAccidentInjury WHEN 1 THEN 1 ELSE 0 END AS 'DefinicionTrabajoSi', CASE WorkAccidentInjury WHEN 0 THEN 1 ELSE 0 END AS 'DefinicionTrabajoNo', ARL AS 'ARL',
				JSON_VALUE(CIE10Code,'$.CODIGO1') AS 'CODIGO1', DIAG1.NOMDIAGNO AS 'Diagnostico1', JSON_VALUE(CIE10Code,'$.CODIGO2') AS 'CODIGO2', DIAG2.NOMDIAGNO AS 'Diagnostico2', JSON_VALUE(CIE10Code,'$.CODIGO3') AS 'CODIGO3', DIAG3.NOMDIAGNO AS 'Diagnostico3', CASE TriageClassification WHEN 1 THEN 1 ELSE 0 END AS 'Triage1',
				CASE TriageClassification WHEN 2 THEN 1 ELSE 0 END AS 'Triage2', CASE TriageClassification WHEN 3 THEN 1 ELSE 0 END AS 'Triage3', CASE TriageClassification WHEN 4 THEN 1 ELSE 0 END AS 'Triage4', CASE TriageClassification WHEN 5 THEN 1 ELSE 0 END AS 'Triage5', EventDescription AS 'DescripcionEvento',
				format(DateOfAttention, 'dd/MM/yyyy') as 'FechaAtencion', format(DateOfAttention, 'HH:mm') as 'HoraAtencion', CASE IECDone WHEN 1 THEN 1 ELSE 0 END AS 'RealizoIECSi', CASE IECDone WHEN 0 THEN 1 ELSE 0 END AS 'RealizoIECNo', format(IECDoneDate  , 'dd/MM/yyyy') AS 'FechaRealizacionIEC', CASE IECResult WHEN 1 THEN 1 ELSE 0 END AS 'ResultadoIECEfectiva',
				CASE IECResult WHEN 2 THEN 1 ELSE 0 END AS 'ResultadoIECFallida', CASE IECType WHEN 1 THEN 1 ELSE 0 END AS 'TipoIECControl', CASE IECType WHEN 2 THEN 1 ELSE 0 END AS 'TipoIECPrioritario', CASE IECModality WHEN 1 THEN 1 ELSE 0 END AS 'ModalidadIECInstitucional', CASE IECModality WHEN 2 THEN 1 ELSE 0 END AS 'ModalidadIECDomiciliaria',
				format(IECMonitoringDate , 'dd/MM/yyyy') AS 'FechaSeguimientoIEC',format(IECClosingDate , 'dd/MM/yyyy') AS 'FechaCierreIEC', DoctorName AS 'NombreMedico', MedicalRecord AS 'RegistroMedico', DoctorId AS 'CedulaMedico', DoctorPhone AS 'TelefonoMedico',
				
				VERSION AS 'VERSION'
	
			From 
				HCFICHA903D FIC
				LEFT JOIN INDIAGNOS DIAG1 ON DIAG1.CODDIAGNO = JSON_VALUE(FIC.CIE10Code,'$.CODIGO1')
				LEFT JOIN INDIAGNOS DIAG2 ON DIAG2.CODDIAGNO = JSON_VALUE(FIC.CIE10Code,'$.CODIGO2')
				LEFT JOIN INDIAGNOS DIAG3 ON DIAG3.CODDIAGNO = JSON_VALUE(FIC.CIE10Code,'$.CODIGO3')

			Where 
				IDFICHANOTIFICACION  = @IdFicha 

END
GO
-- EXECUTE sp_addextendedproperty @name = N'MS_Description', @value = N'Procedimiento almacenado que recupera y formatea el contenido completo de la ficha distrital 903 de notificación obligatoria en salud pública para un caso específico, identificado por el identificador interno de la ficha y su número de ficha. Consulta la tabla HCFICHA903D para obtener todos los datos del evento (lesiones de causa externa, accidentes de tránsito, intoxicaciones, quemaduras, violencias, procedimientos estéticos y conductas autoinfligidas) y cruza con el catálogo INDIAGNOS para obtener el nombre del diagnóstico CIE-10 asociado. Transforma los campos codificados (nivel educativo, estado civil, tipo de vehículo, modalidad de transporte, condición del lesionado, agresor, tipo de lesión) en columnas descriptivas legibles, y desempaqueta estructuras JSON internas para representar múltiples características del evento como columnas individuales. Su propósito es alimentar el formulario imprimible o la vista de detalle de la ficha 903 utilizada para el reporte a vigilancia epidemiológica distrital.', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'PROCEDURE', @level1name = N'SP_HC_ListarFichaDistrital903';
-- GO
-- EXECUTE sp_addextendedproperty @name = N'MS_DescriptionSource', @value = N'backport_from_v25.47c_2026-05-05', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'PROCEDURE', @level1name = N'SP_HC_ListarFichaDistrital903';
-- GO
-- GO
-- GO
-- EXEC sys.sp_addextendedproperty @name=N'MS_BR_Decisions', @value=N'si EducationLevel entre 1 y 13 → Activa la bandera correspondiente al nivel educativo (No escuela, Preescolar, Primaria, Secundaria, Técnico, Universidad, Postgrado, Sin dato); si CivilStatus entre 1 y 7 → Activa la bandera de estado civil (Soltero, Casado, Divorciado, Separado, Viudo, Unión libre, Sin dato); si AreaOfOccurrence = 1 → Clasifica el área de ocurrencia como ''Urbana'' else Si AreaOfOccurrence = 2 se clasifica como ''Rural''; si JSON InjuryOf con claves TRANSITO/CONSUMO/PROCEDIMIENTOSESTETICOS/OTROTIPO/AUTOINFLINGIDAS/PORTERCEROS → Cada bandera de tipo de lesión se obtiene del JSON convertido a BIT; si TypoeOfService = 1 o 2 → Marca tipo de servicio Público o Privado; si TransportMode entre 1 y 4 → Marca modalidad de transporte (Individual, Colectivo, Masivo, Carga); si VehicleType entre 1 y 12 → Marca tipo de vehículo (Automóvil, Moto, Bicicleta, Taxi, Ambulancia, Bicitaxi, Mototaxi, Camioneta, Bus, Transmilenio, SITP, Vehículo de carga); si ConditionOfTheInjured entre 1 y 4 → Marca la condición del lesionado (Peatón, Pasajero, Conductor, Copiloto); si JSON ConsumptionInjuryType con clave = 1 → Marca con ''X'' el tipo de lesión por consumo (Estrangulamiento, Herida, Infección, Intoxicación, Sepsis, Perforación, Hemorragia, Necrosis, Embolia, Depresión); si JSON TypeOfAestheticInjury con clave = 1 → Marca con ''X'' el tipo de lesión estética; si NoOfSurgicalProcedure entre 1 y 4 → Marca número de procedimientos (1, 2, 3 o más); si TypeOfAestheticProfessional entre 1 y 6 → Marca el tipo de profesional estético; si TypeOfAbuse entre 1 y 6 → Marca el tipo de maltrato (Violencia común, Delito sexual, Conyugal, Maltrato menor, Intrafamiliar, Institucional); si AllegedAggressor entre 1 y 3 → Marca el presunto agresor (Familiar, Conocido, Desconocido); si SexOfAggressor entre 1 y 3 → Marca sexo del agresor (Hombre, Mujer, Desconocido); si WasReported / SPAVictim / AlcoholVictim / OthersVictim / SPAAggressor / AlcoholAggressor / OthersAggressor = 1 o 0 → Genera banderas Sí/No para denuncia y consumo de SPA, alcohol u otros en víctima/agresor; si JSON MechanismOrElement con clave = 1 → Marca con ''X'' el mecanismo o elemento (Arma de fuego, cortopunzante, contundente, caída, ahogamiento, otro, artículo consumo/belleza, quemadura); si TypeOfDrowning = 1 o 2 → Marca tipo de ahogamiento (Asfixia o Inmersión); si JSON BurnType con clave = 1 → Marca con ''X'' el tipo de quemadura (Líquido, Llama, Electricidad, Sólido, Vapor, Solar, Rayo, Químico, Pólvora); si CauseOfChemicalInjury = 1 o 2 → Marca la causa de lesión química (Accidente o Agresión); si GunpowderType entre 1 y 3 → Marca tipo de pólvora (Pirotecnia, Negra, Explosiva); si JSON AnatomicalSite con clave = 1 → Marca con ''X'' el sitio anatómico afectado; si LocationOfTheEvent = 1 o 2 → Marca lugar del hecho (Cerrado o Abierto); si Grade entre 1 y 3 → Marca grado de quemadura (Primer, Segundo, Tercer); si Extension entre 1 y 3 → Marca extensión (Menor, Del, Mayor); si JSON Scenery con clave = 1 → Marca con ''X'' el escenario (Vivienda, Trabajo, Estudio, Bares, Otros, Vías, Transporte, Instituciones, Otro); si TypeOfJob = 1 o 2 → Marca tipo de trabajo (Formal o Informal); si WorkAccidentInjury = 1 o 0 → Marca si la definición es accidente de trabajo (Sí/No); si TriageClassification entre 1 y 5 → Marca el nivel de Triage 1 a 5; si IECDone / IECResult / IECType / IECModality según valor → Marca banderas correspondientes a IEC: realización (Sí/No), resultado (Efectiva/Fallida), tipo (Control/Prioritario), modalidad (Institucional/Domiciliaria)', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'PROCEDURE', @level1name=N'SP_HC_ListarFichaDistrital903';
-- GO
